// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 x, uint128 y, address actor) public {
        vm.assume(x <= VALUE_CAP);
        vm.assume(y <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.deal(actor, uint256(x) + uint256(y));

        vm.prank(actor);
        c.Put{value: x}(0);
        vm.prank(actor);
        c.Put{value: y}(0);

        (uint256 unlockTime, uint256 balance) = c.Acc(actor);
        assertTrue(balance == uint256(x) + uint256(y) && unlockTime >= block.timestamp);
    }
}
